$ErrorActionPreference='Stop';$rules=@();$form='1601fq-v2018';$rev='2018-01-01'
function Add-R($id,$phase,$order,$condition,$fields,$message,$ref,$assessment='verified-correct',$behavior='Stops or mutates as described.',$recommend='Apply the rule explicitly and deterministically.',$confidence='high',$questions=@()){
